export default {"id":"komplete-level-15","number":15,"title":"MIDI mode, pedals, other controllers","skillBand":"Textbook","duration":"From the course textbook","summary":"— MIDI mode and pedals (generation specific)","modules":[{"id":"komplete-m-15-1-2","code":"15.1","title":"— MIDI mode and pedals (generation specific)","blurb":"— MIDI mode and pedals (generation specific)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"komplete-kk-l15-1-1","title":"MIDI mode and pedals (generation-specific)","blocks":[{"type":"step","title":"Module 15.1 — MIDI mode and pedals (generation-specific)","blocks":[{"type":"table","headers":["Lesson","Title","Description","Authoring ID"],"rows":[["15.1.1","MK3 MIDI mode","SHIFT + SETTINGS (MIDI). Affects display knobs/buttons 1–8 as a generic MIDI surface.","<code>kk-l15-1-1</code>"],["15.1.2","Stand-alone MIDI controller","MK3 can send/receive on the DIN sockets without a computer. Teach from <em>MIDI Mode</em>; do not invent templates.","<code>kk-l15-1-2</code>"],["15.1.3","DIN as a MIDI interface","Enable the <code>(MIDI)</code> / <code>MIDIIN3</code> / <code>MIDIOUT3</code> rows (Windows vs macOS names in §1.4).","<code>kk-l15-1-3</code>"],["15.1.4","Four MK3 pedals","Settings → Pedal → select socket → Off / Continuous / Switch. Calibrate Continuous. Invert / Swap as needed.","<code>kk-l15-1-4</code>"],["15.1.5","MK3 wheels and Touch Strip","Settings assign CC / Pitchbend / Program Change. Strip default CC 11.","<code>kk-l15-1-5</code>"],["15.1.6","MK3 factory reset","Settings → General → Reset Unit → OK. Last resort.","<code>kk-l15-1-6</code>"],["15.1.7","MIDI Assignment Editor (MK2 / A / M32 only)","Official availability list. Templates, up to four knob/button pages, pedals global. Not for MK3.","<code>kk-l15-1-7</code>"],["15.1.8","Controller Editor leftover","Desktop may still show <strong>Controller Editor</strong>. Confirm against current NI docs whether that app still applies to the student’s generation. <code>{type:'gap'}</code> if NI has retired it for that unit — do not teach a dead app.","<code>kk-l15-1-8</code>"]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> SHIFT+SETTINGS; pedal modes; Assignment Editor is not MK3.   <strong>mustNotCover:</strong> copying Launchkey pedal limits onto MK3 (MK3 has four sockets).   <strong>Sources:</strong> MK3 MIDI Mode; Keyboard Settings; Automation — MIDI Assignment Editor note.   <strong>Practice:</strong> One sustain pedal working in Live on the student’s actual socket.   <strong>Checkpoint:</strong> Written pedal map (socket → mode → MIDI message)."}]}],"minutes":8}],"exercises":[]},{"id":"komplete-m-15-2-3","code":"15.2","title":"— Controller Manager (no NI keyboard connected)","blurb":"— Controller Manager (no NI keyboard connected)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"komplete-kk-l15-2-1","title":"Controller Manager (no NI keyboard connected)","blocks":[{"type":"step","title":"Module 15.2 — Controller Manager (no NI keyboard connected)","blocks":[{"type":"table","headers":["Lesson","Title","Description","Authoring ID"],"rows":[["15.2.1","When this menu exists","Main menu → Controller → Controller Manager. Hidden while an NI Kontrol keyboard is connected.","<code>kk-l15-2-1</code>"],["15.2.2","Load a template","Double-click the controller (or hover → arrow). Header shows the brand icon.","<code>kk-l15-2-2</code>"],["15.2.3","Common mapping","Official templates generally map: eight parameter knobs, previous/next preset, previous/next plug-in slot, previous/next parameter page.","<code>kk-l15-2-3</code>"],["15.2.4","DAW must pass MIDI","Track input = that controller; record-arm on. If the DAW eats the CCs, read the DAW’s MIDI chapter (Live course).","<code>kk-l15-2-4</code>"],["15.2.5","Official list is long","Akai MPK family, Arturia KeyLab / KeyLab Essential, and others are documented with <strong>preset names</strong> (example: MPK249/261 preset <strong>30 Generic</strong>, Bank C). Teach only the controller the student owns; open the official page for that model.","<code>kk-l15-2-5</code>"],["15.2.6","MIDI Learn fallback","If the controller is not in the list, use Level 6 MIDI Learn + Pickup.","<code>kk-l15-2-6</code>"]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> menu path; NI-keyboard lockout; arm the Live track.   <strong>mustNotCover:</strong> a full Akai/Arturia course.   <strong>Sources:</strong> Controller integration.   <strong>Practice:</strong> If the student has a listed non-NI controller, load its template and move eight KK knobs.   <strong>Checkpoint:</strong> Student can say whether they used a factory template or MIDI Learn."}]}],"minutes":8}],"exercises":[]}]};
